import{_ as e,o,c as n,a2 as a}from"./chunks/framework.DajbkT6K.js";const r="/aibutler/docs/img/en/settings-models.png",s="/aibutler/docs/img/en/persona-ai.png",m=JSON.parse('{"title":"Connecting Models","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/models.md","filePath":"en/guide/models.md"}'),i={name:"en/guide/models.md"};function d(l,t,c,h,p,g){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="connecting-models" tabindex="-1">Connecting Models <a class="header-anchor" href="#connecting-models" aria-label="Permalink to &quot;Connecting Models&quot;">​</a></h1><p>A persona needs to be connected to an AI model before it can think and talk. There are two ways: a <strong>Claude subscription</strong>, or <strong>your own API key</strong>. Both can be active at the same time — each persona picks its own.</p><div class="tip custom-block"><p class="custom-block-title">Not sure how to set it up?</p><p>Just ask your persona: &quot;I have a DeepSeek key, how do I connect it?&quot; It will tell you exactly where to click.</p></div><h2 id="two-places-two-different-jobs" tabindex="-1">Two places, two different jobs <a class="header-anchor" href="#two-places-two-different-jobs" aria-label="Permalink to &quot;Two places, two different jobs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where</th><th>What it manages</th></tr></thead><tbody><tr><td><strong>System Settings</strong> (<strong>Settings</strong> at the top right of the main window)</td><td>Stores &quot;keys&quot;: Claude subscription, API keys. Storing one doesn&#39;t mean it&#39;s in use.</td></tr><tr><td><strong>Personas</strong> → a persona → the <strong>AI</strong> tab</td><td>Which key, which engine, and which model this persona uses.</td></tr></tbody></table><p>Store it in System Settings first, then pick it on the persona&#39;s side.</p><h2 id="option-1-claude-subscription" tabindex="-1">Option 1: Claude subscription <a class="header-anchor" href="#option-1-claude-subscription" aria-label="Permalink to &quot;Option 1: Claude subscription&quot;">​</a></h2><p>If you have a Claude Pro or Max subscription, your persona can run on it.</p><ol><li>Open <strong>System Settings</strong> → <strong>Model providers</strong> → <strong>Claude subscription</strong>, and click <strong>Turn on</strong>.</li><li>After confirming, it downloads Anthropic&#39;s Claude Agent SDK (about 110 MB). Once that&#39;s done, click <strong>Restart now</strong>.</li><li>After restarting, click <strong>Log in to Claude</strong> and authorize it in your browser.</li><li>Once it shows <strong>On and logged in</strong>, you&#39;re set.</li></ol><p>Then, on the persona&#39;s <strong>AI</strong> tab, set <strong>Access</strong> to <strong>Use the subscription account</strong>.</p><h2 id="option-2-api-key" tabindex="-1">Option 2: API key <a class="header-anchor" href="#option-2-api-key" aria-label="Permalink to &quot;Option 2: API key&quot;">​</a></h2><h3 id="store-a-key" tabindex="-1">Store a key <a class="header-anchor" href="#store-a-key" aria-label="Permalink to &quot;Store a key&quot;">​</a></h3><p>Open <strong>System Settings</strong> → <strong>Model providers</strong> → <strong>API credentials</strong>, click <strong>+ Add one</strong>, and fill in three fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>What to enter</th></tr></thead><tbody><tr><td>Name</td><td>Anything you&#39;ll recognize, e.g. &quot;DeepSeek&quot; or &quot;company gateway&quot;</td></tr><tr><td>Address (base_url)</td><td>The endpoint your provider gave you; leave blank for the default, <code>https://api.anthropic.com</code></td></tr><tr><td>Key</td><td>The API key your provider gave you</td></tr></tbody></table><p><img src="'+r+'" alt="API credentials in System Settings"></p><p>Click <strong>Save</strong>, then <strong>Test</strong> to confirm it connects. You can store several. The one marked <strong>Default</strong> is used when a persona hasn&#39;t picked a credential, or the one it picked gets removed.</p><h3 id="let-a-persona-use-it" tabindex="-1">Let a persona use it <a class="header-anchor" href="#let-a-persona-use-it" aria-label="Permalink to &quot;Let a persona use it&quot;">​</a></h3><p>Go to <strong>Personas</strong> → a persona → the <strong>AI</strong> tab:</p><ol><li><strong>Access</strong>: choose <strong>Use the key saved in system settings</strong>, then pick which one.</li><li><strong>Engine</strong>: usually <strong>Butler engine (multi-model)</strong>.</li><li><strong>Model</strong>: pick one from the dropdown; if it&#39;s not listed, choose <strong>Other · type a model name</strong> and enter it yourself.</li></ol><p><img src="'+s+'" alt="A persona&#39;s AI tab"></p><p>Reopen the persona for the change to take effect.</p><h3 id="how-to-fill-in-common-providers" tabindex="-1">How to fill in common providers <a class="header-anchor" href="#how-to-fill-in-common-providers" aria-label="Permalink to &quot;How to fill in common providers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Provider</th><th>Address</th><th>How to write the model name</th></tr></thead><tbody><tr><td>Anthropic (official)</td><td>leave blank</td><td>pick from the dropdown</td></tr><tr><td>Gateways using the Anthropic protocol</td><td>the address your gateway gives you</td><td>as given by the gateway</td></tr><tr><td>Qwen (mainland China)</td><td><code>https://dashscope.aliyuncs.com/compatible-mode/v1</code></td><td>prefix with <code>compat/</code>, e.g. <code>compat/qwen-plus</code></td></tr><tr><td>Qwen (international)</td><td><code>https://dashscope-intl.aliyuncs.com/compatible-mode/v1</code></td><td>same as above</td></tr><tr><td>Doubao (Volcano Ark)</td><td><code>https://ark.cn-beijing.volces.com/api/v3</code></td><td>prefix with <code>compat/</code>, followed by the model name from Ark</td></tr><tr><td>Other OpenAI-compatible endpoints</td><td>the address your provider gives you</td><td>prefix with <code>compat/</code></td></tr><tr><td>OpenAI (official)</td><td>leave blank</td><td>prefix with <code>openai/</code>, e.g. <code>openai/gpt-5.4-mini</code></td></tr></tbody></table><p><code>compat/</code> means &quot;connect as an OpenAI-compatible endpoint&quot;; <code>openai/</code> connects to OpenAI&#39;s own newer API. If you&#39;re not sure, try <strong>Test</strong> first, or ask your persona.</p><h2 id="what-s-the-difference-between-the-two-engines" tabindex="-1">What&#39;s the difference between the two engines <a class="header-anchor" href="#what-s-the-difference-between-the-two-engines" aria-label="Permalink to &quot;What&#39;s the difference between the two engines&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Butler engine (multi-model)</th><th>Claude Code</th></tr></thead><tbody><tr><td>What it is</td><td>Built into aibutler</td><td>Anthropic&#39;s official Claude Agent SDK</td></tr><tr><td>Models it supports</td><td>Claude, OpenAI, domestic Chinese models, various gateways</td><td>Claude only</td></tr><tr><td>When it&#39;s used</td><td>The default when using an API key</td><td>Used automatically with a Claude subscription</td></tr></tbody></table><p>Personas on a subscription always run on Claude Code; personas using a key can pick either one — the <strong>Engine</strong> option only appears once the Claude subscription component is installed.</p><h2 id="web-search" tabindex="-1">Web search <a class="header-anchor" href="#web-search" aria-label="Permalink to &quot;Web search&quot;">​</a></h2><p>When using the Butler engine, a persona defaults to the model&#39;s built-in search (some models don&#39;t have one). If it can&#39;t search, or you want to change it, see <a href="/aibutler/docs/en/guide/search.html">Web Search</a>.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>The persona says &quot;has no model selected and cannot reply&quot;</strong> Go to <strong>Personas</strong> → that persona → the <strong>AI</strong> tab and pick a model.</p><p><strong>Getting a 401 error, or &quot;bad key&quot;</strong> Click <strong>Test</strong> on that key in System Settings. If it fails, re-copy and paste the key — watch for extra spaces at either end.</p><p><strong>Getting a 400 error, on and off</strong> Usually the gateway or provider is temporarily rejecting requests — try again shortly. If it keeps happening, try a different route, or send the raw error to your persona and let it look into it.</p><p><strong>Want different personas to use different models</strong> Each persona&#39;s <strong>AI</strong> tab is set independently — they don&#39;t affect each other.</p>',34)])])}const b=e(i,[["render",d]]);export{m as __pageData,b as default};
